/// <summary>
/// COC for WMSArrivalOverview form
/// </summary>
[ExtensionOf(formDataSourceStr(WMSArrivalOverview, WMSArrivalDetailTmp))]
final class METWMSArrivalOverview_WMSArrivalDetailTmpDS_Extension
{
}

Method.Source:
/// <summary>
/// Display item cases 
/// </summary>
/// <param name = "_wMSArrivalDetailTmp">WMSArrivalDetailTmp</param>
/// <returns>Qty</returns>
display Qty itemConvertCases(WMSArrivalDetailTmp _wMSArrivalDetailTmp)
{
    real    sellUOMQty  = 0;
    real    cases       = 0;
    real    factor      = 0;

    if (_wMSArrivalDetailTmp.InventTransType == InventTransType::TransferOrderReceive || _wMSArrivalDetailTmp.InventTransType == InventTransType::Purch)
    {
        InventTransferTable     inventTransferTable = InventTransferTable::find(_wMSArrivalDetailTmp.InventTransRefId);
        InventLocation          inventLocation      = InventLocation::find(inventTransferTable.InventLocationIdFrom);

        UnitOfMeasureSymbol sellUOM = this.getSellUOM(_wMSArrivalDetailTmp.ItemId, inventLocation.InventSiteId, inventLocation.InventLocationId);

        if (sellUOM == _wMSArrivalDetailTmp.METUnitId)
        {
            return _wMSArrivalDetailTmp.InventQty;
        }
        EcoResReleasedProductUnitConverter  ecoResReleasedProductUnitConverter = EcoResReleasedProductUnitConverter::construct();

        factor = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(1, sellUOM, _wMSArrivalDetailTmp.METUnitId, NoYes::Yes, _wMSArrivalDetailTmp.ItemId);

        sellUOMQty = _wMSArrivalDetailTmp.InventQty / factor;

        cases = ecoResReleasedProductUnitConverter.convertGivenUnitSymbols(sellUOMQty, sellUOM, METConstants::unitcase, NoYes::Yes, _wMSArrivalDetailTmp.ItemId);
    }

    return cases;
}

/// <summary>
/// Display item sell UOM
/// </summary>
/// <param name = "_wMSArrivalDetailTmp">WMSArrivalDetailTmp</param>
/// <returns>UnitOfMeasureSymbol</returns>
display UnitOfMeasureSymbol itemSellUOM(WMSArrivalDetailTmp _wMSArrivalDetailTmp)
{
    InventLocationId        inventLocationId;
    UnitOfMeasureSymbol     ret = '';

    if (_wMSArrivalDetailTmp.InventTransType == InventTransType::TransferOrderReceive || _wMSArrivalDetailTmp.InventTransType == InventTransType::Purch)
    {
        if (_wMSArrivalDetailTmp.InventTransType == InventTransType::TransferOrderReceive)
        {
            InventTransferTable     inventTransferTable = InventTransferTable::find(_wMSArrivalDetailTmp.InventTransRefId);

            inventLocationId = inventTransferTable.InventLocationIdFrom;
        }
        else if (_wMSArrivalDetailTmp.InventTransType == InventTransType::Purch)
        {
            PurchTable purchTable = PurchTable::find(_wMSArrivalDetailTmp.InventTransRefId);
            inventLocationId = purchTable.InventLocationId;
        }

        InventLocation          inventLocation      = InventLocation::find(inventLocationId);

        ret = this.getSellUOM(_wMSArrivalDetailTmp.ItemId, inventLocation.InventSiteId, inventLocation.InventLocationId);
    }

    return ret;
}

/// <summary>
/// Get sell UOM
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_inventLocationId">InventLocationId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getSellUOM(ItemId _itemId, InventSiteId _inventSiteId, InventLocationId _inventLocationId)
{
    InventItemSalesSetup        inventItemSalesSetup;
    InventDim                   inventDim;
    UnitOfMeasureSymbol         ret;

    if (_itemId)
    {
        select firstonly METSalesUnit, ItemId, InventDimId from inventItemSalesSetup
                where inventItemSalesSetup.ItemId == _itemId
            exists join inventDim
                where inventItemSalesSetup.InventDimId == inventDim.inventDimId
                && inventDim.InventSiteId == _inventSiteId;

        if (inventItemSalesSetup.METSalesUnit)
        {
            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!inventItemSalesSetup.METSalesUnit && !ret)
        {
            inventItemSalesSetup = InventItemSalesSetup::find(_itemId, METConstants::AllowBlank);

            ret = inventItemSalesSetup.METSalesUnit;
        }
        else if (!ret)
        {
            InventTableModule  inventTableModule = InventTableModule::find(_itemId, ModuleInventPurchSales::Sales);

            ret = inventTableModule.UnitId;
        }            
    }
    return ret;
}
